def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n < 3:
        return 'C'
    opp_c = 0
    opp_d = 0
    my_c = 0
    my_d = 0
    for (a, b) in history:
        if b == 'C':
            opp_c += 1
        else:
            opp_d += 1
        if a == 'C':
            my_c += 1
        else:
            my_d += 1
    total = n
    opp_defect_ratio = opp_d / total
    opp_recent = history[-5:]
    recent_opp_d = sum(1 for (a, b) in opp_recent if b == 'D')
    recent_opp_c = len(opp_recent) - recent_opp_d
    if n < 10:
        if recent_opp_d >= 3:
            return 'D'
        return 'C'
    last_mine, last_opp = history[-1]
    if n >= 20:
        if opp_d == 0:
            return 'C'
        blocks = 10
        segment_size = n // blocks
        recent_def = 0
        sample = min(30, n)
        for (a, b) in history[-sample:]:
            if b == 'D':
                recent_def += 1
        recent_ratio = recent_def / sample
        if recent_ratio > 0.6:
            return 'D'
        if recent_ratio < 0.2:
            return 'C'
    prev_last_opp = None
    if n >= 2:
        prev_last_opp = history[-2][1]
    if last_opp == 'D':
        if n >= 5:
            d_count = sum(1 for (a, b) in history[-5:] if b == 'D')
            if d_count >= 2:
                return 'D'
        return 'D'
    else:
        if n >= 10:
            d_count = sum(1 for (a, b) in history[-10:] if b == 'D')
            if d_count >= 3:
                return 'D'
        return 'C'
